  function englishFallback(trimmed){
    let translated=en.get(trimmed);
    if(!translated){for(const [re,to] of patterns){if(re.test(trimmed)){translated=trimmed.replace(re,to);break;}}}
    if(!translated){let partial=trimmed;for(const [from,to] of fragments)partial=partial.split(from).join(to);if(partial!==trimmed)translated=partial;}
    return translated;
  }
  function text(value){
    if(current === 'cs') return value;
    const trimmed=value.trim(); if(!trimmed) return value;
    let translated=dictionaries[current]?.get(trimmed) || englishFallback(trimmed);
    if(!translated) return value;
    const lead=value.match(/^\s*/)[0], tail=value.match(/\s*$/)[0]; return lead+translated+tail;
  }
  let applying=false;
  function apply(root=document){
    if(current==='cs'||applying)return; applying=true;
    const nodes=[];
    if(root.nodeType===Node.TEXT_NODE)nodes.push(root);
    else {const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(w.nextNode())nodes.push(w.currentNode);}
    for(const n of nodes){if(!['SCRIPT','STYLE'].includes(n.parentElement?.tagName)){const v=text(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;}}
    const els=root.nodeType===Node.ELEMENT_NODE?[root,...root.querySelectorAll('*')]:[...document.querySelectorAll('*')];
    for(const el of els)for(const a of ['placeholder','title','aria-label'])if(el.hasAttribute?.(a)){const v=text(el.getAttribute(a));if(v!==el.getAttribute(a))el.setAttribute(a,v);}
    document.documentElement.lang=current; applying=false;
  }
