  window.MTI18n={lang:()=>current,locale:()=>localeByLanguage[current],text,apply,set,supported};
  apply();
  new MutationObserver(ms=>{if(applying)return;for(const m of ms){if(m.type==='characterData')apply(m.target);else for(const n of m.addedNodes)apply(n);}}).observe(document.documentElement,{subtree:true,childList:true,characterData:true});
